import { useState, useEffect } from 'react';
import { Spinner, Modal, Btn, useToast } from '../../components/shared/index.jsx';
import { useAuth } from '../../context/AuthContext';
import { getJobPostings, submitResume } from '../../api/index.js';

export function EmployeeCareersPage() {
  const { user } = useAuth();
  const name  = user?.full_name ?? '';
  const email = user?.email ?? '';
  const toast = useToast();

  const [jobs, setJobs]           = useState([]);
  const [loading, setLoading]     = useState(true);
  const [selected, setSelected]   = useState(null);
  const [search, setSearch]       = useState('');
  const [showApply, setShowApply] = useState(false);
  const [file, setFile]           = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult]       = useState(null);

  // --- Load Jobs (Public Access) ---
  useEffect(() => {
    getJobPostings()
      .then(data => { 
        const activeJobs = Array.isArray(data) ? data.filter(j => j.is_active !== false) : [];
        setJobs(activeJobs); 
      })
      .catch(() => toast('Could not reach API', 'error'))
      .finally(() => setLoading(false));
  }, []);

  const filtered = jobs.filter(j =>
    j.title?.toLowerCase().includes(search.toLowerCase()) ||
    (j.description || '').toLowerCase().includes(search.toLowerCase())
  );

  // --- NEW: Auth Guard for Application ---
  const handleApplyClick = (job) => {
    if (!user) {
      toast('Please sign in as a candidate to apply', 'info');
      // Optional: window.location.href = '/login'; 
      return;
    }
    setSelected(job);
    setShowApply(true);
    setResult(null);
  };

  // --- Reset Modal State ---
  const handleCloseModal = () => {
    setShowApply(false);
    setFile(null);
    setResult(null);
  };

  // --- Handle File Selection ---
  const onFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile && !selectedFile.name.toLowerCase().endsWith('.pdf')) {
      toast('Please upload a PDF file', 'error');
      return;
    }
    setFile(selectedFile);
  };

  // --- Submit Application (Authenticated) ---
  const handleApply = async () => {
    if (!file) { toast('Please upload your resume', 'error'); return; }

    setSubmitting(true);
    setResult(null);

    const fd = new FormData();
    fd.append('job', selected.id);
    fd.append('resume_file', file);
    fd.append('candidate_name', name);
    fd.append('candidate_email', email);

    try {
      const data = await submitResume(fd);
      if (data.detail) {
        toast(data.detail, 'error');
      } else {
        setResult(data);
        toast('Application analyzed successfully!', 'success');
      }
    } catch (e) { 
      toast('Pipeline Error: ' + e.message, 'error'); 
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div style={{ background: 'var(--gray-25)', minHeight: '100vh' }}>
      {/* Hero Section */}
      <section style={{ background: 'var(--white)', borderBottom: '1px solid #EAECF0', padding: '64px 32px 56px', textAlign: 'center' }}>
        <div style={{ maxWidth: 1280, margin: '0 auto', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 20 }}>
          <h1 style={{ fontFamily: 'var(--serif)', fontSize: 'clamp(32px,5vw,48px)', fontWeight: 400, lineHeight: 1.1, maxWidth: 800 }}>
            The future of HR is built on <em style={{ color: 'var(--red)', fontStyle: 'italic' }}>intelligence.</em>
          </h1>
          <p style={{ fontSize: 16, color: 'var(--gray-500)', maxWidth: 500 }}>Apply to our open roles and see your match score in real-time.</p>

          <div style={{ width: '100%', maxWidth: 500, position: 'relative', marginTop: 12 }}>
            <input 
              value={search} 
              onChange={e => setSearch(e.target.value)} 
              placeholder="Search roles..."
              style={{ width: '100%', padding: '14px 20px 14px 45px', border: '1px solid #EAECF0', background: 'var(--gray-50)', borderRadius: 12, fontSize: 14, outline: 'none' }}
            />
            <svg style={{ position: 'absolute', left: 16, top: '50%', transform: 'translateY(-50%)', width: 18, height: 18, stroke: 'var(--gray-400)', fill: 'none' }} viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          </div>
        </div>
      </section>

      {/* Main Content */}
      <div style={{ maxWidth: 1200, margin: '0 auto', padding: '48px 32px', display: 'grid', gridTemplateColumns: '1fr 360px', gap: 32, alignItems: 'start' }}>

        {/* Job List */}
        <div>
          <h3 style={{ fontSize: 18, fontWeight: 700, marginBottom: 20 }}>Available Positions ({filtered.length})</h3>
          {loading ? (
            <div style={{ padding: 60, textAlign: 'center' }}><Spinner /></div>
          ) : (
            <div style={{ display: 'grid', gap: 16 }}>
              {filtered.map(j => (
                <div 
                  key={j.id} 
                  onClick={() => setSelected(j)}
                  style={{
                    background: 'var(--white)', padding: 24, borderRadius: 20, cursor: 'pointer',
                    border: `2px solid ${selected?.id === j.id ? 'var(--red)' : 'transparent'}`,
                    boxShadow: '0 2px 8px rgba(0,0,0,0.04)', transition: '0.2s'
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h4 style={{ fontWeight: 700, fontSize: 18 }}>{j.title}</h4>
                    <span style={{ fontSize: 12, color: 'var(--gray-400)' }}>{j.min_experience_years}+ Years</span>
                  </div>
                  <p style={{ fontSize: 14, color: 'var(--gray-500)', marginTop: 8, overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical' }}>
                    {j.description}
                  </p>
                  <div style={{ marginTop: 16, display: 'flex', justifyContent: 'flex-end' }}>
                    {/* Using handleApplyClick for Auth Guard */}
                    <Btn size="sm" onClick={(e) => { e.stopPropagation(); handleApplyClick(j); }}>Apply Now</Btn>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Sidebar Selection */}
        <aside style={{ position: 'sticky', top: 32 }}>
          {!selected ? (
            <div style={{ padding: 40, background: 'var(--white)', borderRadius: 20, border: '1px dashed #EAECF0', textAlign: 'center', color: 'var(--gray-400)' }}>
              Select a job to view details
            </div>
          ) : (
            <div style={{ background: 'var(--white)', padding: 28, borderRadius: 24, border: '1px solid #EAECF0', boxShadow: 'var(--shadow-md)' }}>
              <div style={{ color: 'var(--red)', fontWeight: 700, fontSize: 11, textTransform: 'uppercase', marginBottom: 8 }}>Job Details</div>
              <h2 style={{ fontSize: 22, fontWeight: 700, marginBottom: 12 }}>{selected.title}</h2>
              <p style={{ fontSize: 14, color: 'var(--gray-600)', lineHeight: 1.6, marginBottom: 24 }}>{selected.description}</p>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginBottom: 24 }}>
                <div style={{ fontSize: 13 }}><strong>Experience:</strong> {selected.min_experience_years}+ years</div>
                <div style={{ fontSize: 13 }}><strong>Education:</strong> {selected.required_degree}</div>
              </div>

              {/* Using handleApplyClick for Auth Guard */}
              <Btn onClick={() => handleApplyClick(selected)} style={{ width: '100%' }}>Submit Application</Btn>
            </div>
          )}
        </aside>
      </div>

      {/* Application Modal */}
      <Modal open={showApply} onClose={handleCloseModal} title={result ? "Analysis Results" : `Apply for ${selected?.title}`} maxWidth={500}>
        {result ? (
          <div style={{ paddingBottom: 10 }}>
            <div style={{ textAlign: 'center', marginBottom: 24 }}>
              <div style={{ fontSize: 12, color: 'var(--gray-500)', fontWeight: 700 }}>ATS MATCH SCORE</div>
              <div style={{ fontSize: 56, fontWeight: 800, color: result.ats_score > 70 ? '#22C55E' : 'var(--red)' }}>
                {Math.round(result.ats_score)}%
              </div>
            </div>

            {[
              { label: 'Skills', score: result.skills_score, color: '#E8321A' },
              { label: 'Experience', score: result.experience_score, color: '#3B82F6' },
              { label: 'Education', score: result.education_score, color: '#F59E0B' }
            ].map(item => (
              <div key={item.label} style={{ marginBottom: 16 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>
                  <span>{item.label}</span>
                  <span>{Math.round(item.score)}%</span>
                </div>
                <div style={{ height: 6, background: 'var(--gray-100)', borderRadius: 3 }}>
                  <div style={{ height: '100%', width: `${item.score}%`, background: item.color, borderRadius: 3, transition: 'width 1s ease' }} />
                </div>
              </div>
            ))}

            <Btn variant="ghost" onClick={handleCloseModal} style={{ width: '100%', marginTop: 20 }}>Close</Btn>
          </div>
        ) : (
          <div>
            <div 
              onClick={() => document.getElementById('resume-upload').click()}
              style={{ 
                padding: '40px 20px', border: '2px dashed #EAECF0', borderRadius: 16, 
                textAlign: 'center', cursor: 'pointer', background: 'var(--gray-50)', marginBottom: 20 
              }}
            >
              <input type="file" id="resume-upload" hidden accept=".pdf" onChange={onFileChange} />
              <div style={{ fontSize: 14, fontWeight: 600 }}>
                {file ? file.name : "Click to upload Resume (PDF)"}
              </div>
              <div style={{ fontSize: 12, color: 'var(--gray-400)', marginTop: 4 }}>Maximum size 10MB</div>
            </div>

            <div style={{ display: 'flex', gap: 12 }}>
              <Btn variant="ghost" onClick={handleCloseModal} style={{ flex: 1 }}>Cancel</Btn>
              <Btn onClick={handleApply} disabled={submitting} style={{ flex: 1 }}>
                {submitting ? "Analyzing..." : "Submit"}
              </Btn>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
